import{_ as a,a as i,a3 as t,o as s}from"./chunks/framework.edeurCMZ.js";const k=JSON.parse('{"title":"Configure a Local HPCC Platform Runtime on macOS","description":"","frontmatter":{},"headers":[],"relativePath":"devdoc/RunningHPCCOnMacOS.md","filePath":"devdoc/RunningHPCCOnMacOS.md","lastUpdated":1788274664000}'),n={name:"devdoc/RunningHPCCOnMacOS.md"};function o(l,e,c,r,d,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="configure-a-local-hpcc-platform-runtime-on-macos" tabindex="-1">Configure a Local HPCC Platform Runtime on macOS <a class="header-anchor" href="#configure-a-local-hpcc-platform-runtime-on-macos" aria-label="Permalink to &quot;Configure a Local HPCC Platform Runtime on macOS&quot;">​</a></h1><p>HPCC Platform&#39;s default bare-metal configuration assumes Linux network and process behavior. After installing HPCC Platform on macOS, make the following changes before launching the cluster for the first time.</p><p>The installed configuration files are normally in <code>/etc/HPCCSystems</code>. For an installation staged with <code>DESTDIR</code>, they are in <code>&lt;DESTDIR&gt;/etc/HPCCSystems</code>. Use the location that matches the installation.</p><h2 id="bind-services-to-the-loopback-interface" tabindex="-1">Bind services to the loopback interface <a class="header-anchor" href="#bind-services-to-the-loopback-interface" aria-label="Permalink to &quot;Bind services to the loopback interface&quot;">​</a></h2><p>Edit the installed <code>environment.conf</code> and set <code>interface</code> to the macOS loopback interface:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=lo0</span></span></code></pre></div><p>The Linux loopback interface name <code>lo</code> is not valid on macOS.</p><h2 id="disable-roxie-background-nice-adjustment" tabindex="-1">Disable Roxie background nice adjustment <a class="header-anchor" href="#disable-roxie-background-nice-adjustment" aria-label="Permalink to &quot;Disable Roxie background nice adjustment&quot;">​</a></h2><p>macOS does not permit the Roxie background workers to use the default nice adjustment in the same way as Linux. Edit the installed <code>environment.xml</code> and add <code>adjustBGThreadNiceValue=&quot;0&quot;</code> to the main <code>RoxieCluster</code> element:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RoxieCluster</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> allFilesDynamic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">                adjustBGThreadNiceValue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">                allowedPipePrograms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RoxieCluster</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Add the attribute only to the <code>RoxieCluster</code> definition under <code>Software</code>, not to the later topology references such as <code>&lt;RoxieCluster process=&quot;myroxie&quot;/&gt;</code>.</p>`,11)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
